<script>
document.addEventListener('DOMContentLoaded',function(){
 var buttons=[].slice.call(document.querySelectorAll('[data-tb-tab]')),panels=[].slice.call(document.querySelectorAll('[data-tb-panel]'));
 function openTab(name){buttons.forEach(function(b){b.classList.toggle('active',b.getAttribute('data-tb-tab')===name)});panels.forEach(function(p){p.classList.toggle('active',p.getAttribute('data-tb-panel')===name)});if(history.replaceState)history.replaceState(null,'','#'+name)}
 buttons.forEach(function(button){button.addEventListener('click',function(){openTab(this.getAttribute('data-tb-tab'))})});var requested=location.hash.replace('#','');if(document.querySelector('[data-tb-panel="'+requested+'"]'))openTab(requested);
 var bg=document.querySelector('[name=top_bar_background_color]'),text=document.querySelector('[name=top_bar_text_color]'),link=document.querySelector('[name=top_bar_link_color]'),message=document.querySelector('#new-announcement-message');function preview(){document.querySelectorAll('[data-tb-preview],[data-tb-mobile-preview]').forEach(function(p){p.style.background=bg.value;p.style.color=text.value;p.querySelectorAll('span:last-child').forEach(function(a){a.style.color=link.value})});if(message)document.querySelectorAll('[data-tb-preview-message]').forEach(function(x){x.textContent=message.value||'Your announcement appears here'})}[bg,text,link,message].forEach(function(x){if(x)x.addEventListener('input',preview)});preview();
});
</script>
